                key = i + j
                if key not in diagonals:
                    diagonals[key] = []
                diagonals[key].append(grid[i][j])

        # Step 2: Sort diagonals as per the problem's rules
        for key in diagonals:
            if key < n:
                # Bottom-left triangle (including middle): sort non-increasing
                diagonals[key].sort(reverse=True)
            else:
                # Top-right triangle: sort non-decreasing
                diagonals[key].sort()

        # Step 3: Reconstruct the matrix
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                key = i + j
                # Extract the first element of the diagonal and assign it
                # back to the correct position
                # But need to pop the first element and assign to result[i][j]
                val = diagonals[key].pop(0)
                result[i][j] = val

        return result

