    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Helper function to collect elements of a diagonal
        def collect_diagonal(diagonal_id, is_bottom_left):
            elements = []
            if is_bottom_left:
                # Bottom-left diagonals: i - j is constant
                for i in range(n):
                    j = i - diagonal_id
                    if 0 <= j < n:
                        elements.append(grid[i][j])
            else:
                # Top-right diagonals: i + j is constant
                for i in range(n):
                    j = diagonal_id - i
                    if 0 <= j < n:
                        elements.append(grid[i][j])
            return elements

        # Helper function to place sorted elements back into the diagonal
        def place_diagonal(diagonal_id, sorted_elements, is_bottom_left):
            index = 0
            if is_bottom_left:
                # Place back into bottom-left diagonals
                for i in range(n):
                    j = i - diagonal_id
                    if 0 <= j < n:
                        grid[i][j] = sorted_elements[index]
                        index += 1
            else:
                # Place back into top-right diagonals
                for i in range(n):
                    j = diagonal_id - i
                    if 0 <= j < n:
                        grid[i][j] = sorted_elements[index]
                        index += 1

        # Process bottom-left triangle diagonals (i - j is non-negative)
        for d in range(n - 1, -1, -1):
            elements = collect_diagonal(d, is_bottom_left=True)
            elements.sort(reverse=True)
            place_diagonal(d, elements, is_bottom_left=True)

