class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0

        # Function to check if a string is a palindrome
        def is_palindrome(string):
            return string == string[::-1]

        # Iterate over all possible substrings of s and t
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substr_s = s[i:j]
                for k in range(len(t)):
                    for l in range(k + 1, len(t) + 1):
                        substr_t = t[k:l]
                        combined = substr_s + substr_t
                        if is_palindrome(combined):
                            max_len = max(max_len, len(combined))

        # Also consider cases where one of the substrings is empty
        # (e.g., just the substring from s or just from t)
        # These cases are already covered in the above loops

        # Consider the case where we take the longest palindromic substring from t alone
        max_t_pal = max(len(sub) for sub in [t[i:j] for i in range(len(t)) for j in range(i + 1, len(t) + 1) if is_palindrome(t[i:j])])
        max_s_pal = max(len(sub) for sub in [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1) if is_palindrome(s[i:j])])
        max_len = max(max_len, max_t_pal, max_s_pal)

        return max_len

