    def minLength(self, s: str, numOps: int) -> int:
        from collections import deque

        # Convert the string to a list of integers for easier manipulation
        s_list = [int(c) for c in s]
        n = len(s_list)
        if n == 0:
            return 0

        # Process the list by grouping runs of same characters
        runs = []
        current_val = s_list[0]
        count = 1
        for i in range(1, n):
            if s_list[i] == current_val:
                count += 1
            else:
                runs.append((current_val, count))
                current_val = s_list[i]
                count = 1
        runs.append((current_val, count))

        # If all characters are the same, we can split the maximum run using flips
        if len(runs) == 1:
            max_run = runs[0][1]
            if max_run <= numOps * 2:
                return 1  # Can reduce to 1
            else:
                # The minimum length after using all flips is ceil(max_run / (numOps + 1))
                # But since we can reduce the run by 2 per flip, the best is to split as much as possible
                return max(1, max_run - 2 * numOps)
        else:
            # We need to reduce the largest run
            # Sort the runs by their length in descending order
            runs.sort(key=lambda x: -x[1])
            max_run = runs[0][1]
            # How much can we reduce the max run with numOps flips?
            # Each flip can reduce the max run by at most 2 (splitting it into smaller parts)
            reduction = min(numOps * 2, max_run)
            reduced_length = max_run - reduction
            # The minimum possible maximum length is the max between the reduced max run and other runs
            # If reduced_length is 0, then we can reduce to 1
            if reduced_length <= 0:
                return 1
            else:
                return max(reduced_length, max([run[1] for run in runs[1:]]))

