class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        def dijkstra(graph, start, end):
            # Initialize the shortest distance to all nodes as infinity
            dist = [float('inf')] * n
            dist[start] = 0
            heap = [(0, start)]  # (distance, node)

            while heap:
                current_dist, u = heapq.heappop(heap)
                if u == end:
                    break
                if current_dist > dist[u]:
                    continue
                for v, _ in graph[u]:
                    if dist[v] > dist[u] + 1:
                        dist[v] = dist[u] + 1
                        heapq.heappush(heap, (dist[v], v))
            return dist[end]

        # Initialize the graph with the original roads
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append((i + 1, 1))  # weight is 1

        result = []

        # Process each query and update the graph
        for u, v in queries:
            # Add the new road to the graph
            graph[u].append((v, 1))
            # Run Dijkstra to get the shortest distance from 0 to n-1
            shortest = dijkstra(graph, 0, n - 1)
            result.append(shortest)

        return result

