class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        n = len(word)
        if numFriends >= n:
            # Only one possible split, all single letters, so the max is the max letter
            return max(word)

        # Generate all possible splits into numFriends parts
        max_str = ""
        # Generate all possible positions to split
        for split_indices in itertools.combinations(range(1, n - numFriends + 1), numFriends - 1):
