class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0

        # Initialize the DP table. dp[i][k] represents the number of ways to assign values to arr1[0..i] such that arr1[i] = k.
        # For the first element, possible values are from 0 to nums[0], but we need to track constraints.
        # We can use a list of dictionaries for each step.

        # Start with the first element
        dp_prev = {}
        max_val = nums[0]
        for k in range(0, max_val + 1):
            dp_prev[k] = 1  # Only one way to assign arr1[0] = k

        for i in range(1, n):
            dp_current = {}
            for k in range(0, nums[i] + 1):
                # arr1[i] = k, arr2[i] = nums[i] - k
                # arr1[i] must be >= arr1[i-1]
                # arr2[i] = nums[i] - k must be <= arr2[i-1] = nums[i-1] - prev_val
                # So for all prev_vals in dp_prev, we check if k >= prev_val and nums[i] - k <= nums[i-1] - prev_val
                for prev_val, count in dp_prev.items():
                    if k >= prev_val:
                        arr2_i = nums[i] - k
                        arr2_prev = nums[i-1] - prev_val
                        if arr2_i <= arr2_prev:
                            dp_current[k] = (dp_current.get(k, 0) + count) % MOD
            dp_prev = dp_current
            # If dp_prev is empty, no valid configuration exists
            if not dp_prev:
                return 0

        # Sum all possible values of arr1[n-1] in dp_prev to get total valid pairs
        total = sum(dp_prev.values()) % MOD
        return total

