    def minCostGoodCaption(self, caption: str) -> str:
        from collections import deque, defaultdict

        n = len(caption)
        # Define a helper to check if a string is a good caption
        def is_good(s):
            i = 0
            while i < len(s):
                if i + 2 >= len(s):
                    return False
                current_char = s[i]
                j = i
                while j < len(s) and s[j] == current_char:
                    j += 1
                if j - i < 3:
                    return False
                i = j
            return True

        # Generate all possible characters for each position
        def possible_chars(ch):
            chars = set()
            if ch != 'a':
                chars.add(ch - 1)
            if ch != 'z':
                chars.add(ch + 1)
            chars.add(ch)
            return chars

        # Start BFS with the original caption
        # Each state is (current_string, cost, current_position)
        # We also need to track visited states to avoid cycles
        visited = set()
        initial = (caption, 0, 0)  # (string, cost, position)
        visited.add((caption, 0))

        queue = deque()
        queue.append((caption, 0, 0))

        # Keep track of the best (minimal cost and lex smallest) valid caption found
        best_caption = None
        min_cost = float('inf')

        while queue:
            current_str, cost, pos = queue.popleft()
            if is_good(current_str):
                if cost < min_cost or (cost == min_cost and current_str < best_caption):
                    min_cost = cost
                    best_caption = current_str
                continue

            # Try to modify the current character and try to build a good caption
            # For each position, try changing it to possible characters
            if pos < n:
                current_char = current_str[pos]
                for next_char in possible_chars(current_char):
                    new_str = current_str[:pos] + chr(next_char) + current_str[pos+1:]
                    if (new_str, cost + 1) not in visited:
                        visited.add((new_str, cost + 1))
                        queue.append((new_str, cost + 1, pos + 1))

        if best_caption is not None:
