        import bisect

        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # Binary search on possible distances
        left, right = 0, 2 * side  # Maximum possible Manhattan distance is 2*side
        answer = 0

        # Precompute all pairwise Manhattan distances
        n = len(points)
        all_pairs = [[manhattan(p1, p2) for p2 in points] for p1 in points]

        def is_possible(d):
            # Try to select k points such that any two have at least d distance
            # We will greedily try to select the points that are spaced at least d apart.
            # However, since we are maximizing d, and k is small, we can try all combinations of k points
            # and check if the minimum pairwise distance is >= d

            from itertools import combinations

            for subset in combinations(points, k):
                min_dist = min(manhattan(p1, p2) for p1, p2 in combinations(subset, 2))
