from typing import List

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n = len(moveTime)
        m = len(moveTime[0])
        if n == 0 or m == 0:
            return 0

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Initialize a min-heap for Dijkstra's algorithm
        heap = [(0, 0, 0)]  # (arrival_time, row, col)
        # Initialize the distance matrix with infinity
        dist = [[float('inf')] * m for _ in range(n)]
        dist[0][0] = max(0, moveTime[0][0])  # start at (0,0), time is 0, but must wait for moveTime[0][0]

        while heap:
            time, r, c = heapq.heappop(heap)
            if r == n - 1 and c == m - 1:
                return time
            if time > dist[r][c]:
                continue  # we have already found a better path to this cell
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    # Time to reach neighbor is max of (arrival time + 1) and moveTime[nr][nc]
                    new_time = max(time + 1, moveTime[nr][nc])
                    if new_time < dist[nr][nc]:
                        dist[nr][nc] = new_time
                        heapq.heappush(heap, (new_time, nr, nc))

        return dist[n-1][m-1]  # In case the destination is not reachable (though problem says it is)

