class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # Initialize a 3D DP table: dp[i][j][x] = number of ways to reach (i,j) with XOR value x
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

        # Start at (0, 0)
        initial_xor = grid[0][0]
        dp[0][0][initial_xor] = 1

        # Fill the DP table
        for i in range(m):
            for j in range(n):
                # Skip if current cell is (0,0)
                if i == 0 and j == 0:
                    continue

                # Get the current cell's value
                current_val = grid[i][j]

                # Try to come from the top (i-1, j)
                if i > 0:
                    for x in range(16):
                        if dp[i-1][j][x] > 0:
                            new_xor = (x ^ current_val) % 16
                            dp[i][j][new_xor] = (dp[i][j][new_xor] + dp[i-1][j][x]) % MOD

                # Try to come from the left (i, j-1)
                if j > 0:
                    for x in range(16):
                        if dp[i][j-1][x] > 0:
                            new_xor = (x ^ current_val) % 16
                            dp[i][j][new_xor] = (dp[i][j][new_xor] + dp[i][j-1][x]) % MOD

        # The answer is the number of paths that end at (m-1, n-1) with XOR value equal to k
        return dp[m-1][n-1][k] % MOD

