from typing import List
from collections import deque

class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        total = 0
        for i in range(n):
            for j in range(n):
                total += fruits[i][j]

        # Function to collect fruits from a path and return the set of visited cells
        def collect_path(start, end, steps):
            visited = set()
            queue = deque()
            queue.append((start[0], start[1], 0))
            visited.add((start[0], start[1]))
            while queue:
                i, j, step = queue.popleft()
                if step == steps:
                    continue
                if i == end[0] and j == end[1]:
                    continue
                if start == (0, 0):
                    # Child from (0,0): can move to (i+1, j), (i+1, j+1), (i, j+1)
                    next_positions = [(i+1, j), (i+1, j+1), (i, j+1)]
                elif start == (0, n-1):
                    # Child from (0, n-1): can move to (i+1, j-1), (i+1, j), (i+1, j+1)
                    next_positions = [(i+1, j-1), (i+1, j), (i+1, j+1)]
                else:
                    # Child from (n-1, 0): can move to (i-1, j+1), (i, j+1), (i+1, j+1)
                    next_positions = [(i-1, j+1), (i, j+1), (i+1, j+1)]

                for ni, nj in next_positions:
                    if 0 <= ni < n and 0 <= nj < n:
                        if (ni, nj) not in visited:
                            if (ni, nj) == (end[0], end[1]) and step + 1 == steps:
                                visited.add((ni, nj))
                            else:
                                queue.append((ni, nj, step + 1))
                                visited.add((ni, nj))
            return visited

        # Start points for each child
        start1 = (0, 0)
        start2 = (0, n-1)
        start3 = (n-1, 0)
        end = (n-1, n-1)
        steps = n - 1

        # Collect the rooms visited by each child
        path1 = collect_path(start1, end, steps)
        path2 = collect_path(start2, end, steps)
        path3 = collect_path(start3, end, steps)

        # Combine all visited rooms and sum the fruits
        all_visited = path1.union(path2).union(path3)
        result = sum(fruits[i][j] for i, j in all_visited)

        return result

