    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        from collections import defaultdict

        # Precompute cost to change one character to another
        def cost(c1, c2):
            return min(abs(ord(c1) - ord(c2)), 26 - abs(ord(c1) - ord(c2)))

        n = len(s)
        # Precompute a 2D cost matrix
        cost_matrix = [[cost(s[i], s[j]) for j in range(n)] for i in range(n)]

        # Memoization cache for DP
        memo = {}

        def dp(i, j, k_left):
            if i > j:
                return 0
            if (i, j, k_left) in memo:
                return memo[(i, j, k_left)]
            # Try to match the two ends
            min_cost = float('inf')
            for c in range(26):
                char = chr(ord('a') + c)
                cost = cost(s[i], char) + cost(s[j], char)
                if cost <= k_left:
                    min_cost = min(min_cost, cost)
            if min_cost <= k_left:
                # We can make both ends match
                res = 2 + dp(i + 1, j - 1, k_left - min_cost)
                memo[(i, j, k_left)] = res
                return res
            else:
                # Try taking the max of excluding one end
                res = max(dp(i + 1, j, k_left), dp(i, j - 1, k_left))
                memo[(i, j, k_left)] = res
                return res

        # Start from the whole string, with k operations
        max_len = dp(0, n - 1, k)
        return max_len

