class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        # Precompute for each cell, the maximum value in a rectangle from (0,0) to (i,j)
        # For this, we can use a 2D array that stores the maximum value of the submatrix ending at (i,j)
        max_2d = [[0] * n for _ in range(m)]

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    max_2d[i][j] = grid[i][j]
                elif i == 0:
                    max_2d[i][j] = max(max_2d[i][j - 1], grid[i][j])
                elif j == 0:
                    max_2d[i][j] = max(max_2d[i - 1][j], grid[i][j])
                else:
                    max_2d[i][j] = max(max_2d[i - 1][j], max_2d[i][j - 1], grid[i][j])

        # Iterate through all possible top-left and bottom-right corners of submatrices
        for x1 in range(m):
            for y1 in range(n):
                for x2 in range(x1, m):
                    for y2 in range(y1, n):
                        # Now, we need the maximum in the submatrix (x1,y1) to (x2,y2)
                        # Since rows are sorted, we can find the max row-wise
                        max_in_sub = 0
                        for i in range(x1, x2 + 1):
                            current_row_max = max(grid[i][y1:y2 + 1])
                            if current_row_max > max_in_sub:
                                max_in_sub = current_row_max
                        if max_in_sub <= k:
                            count += 1
        return count

