    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)

        # Precompute prefix sum of vowels
        prefix_vowels = [0] * (n + 1)
        for i in range(n):
            prefix_vowels[i + 1] = prefix_vowels[i] + (1 if word[i] in vowels else 0)

        def is_valid(start, end):
            # Count total vowels in the substring [start, end]
            total_vowels = prefix_vowels[end + 1] - prefix_vowels[start]
            # Check if all vowels are present
            if total_vowels < 5:
                return False
            # Check if all vowels are present (not just count)
            # So we need to check that each vowel appears at least once
            # Let's collect all vowels in the substring
            vowels_in_sub = set()
            for i in range(start, end + 1):
                if word[i] in vowels:
                    vowels_in_sub.add(word[i])
            if len(vowels_in_sub) < 5:
                return False
            # Count consonants in the substring
            total_consonants = (end - start + 1) - total_vowels
            return total_consonants == k

