        full_lcm = compute_lcm(nums)
        max_score = max(max_score, full_gcd * full_lcm)

        # Case 2: consider each possible removal of one element
        for i in range(len(nums)):
            temp = nums[:i] + nums[i+1:]
            if not temp:
                continue
            g = compute_gcd(temp)
            l = compute_lcm(temp)
            max_score = max(max_score, g * l)

        return max_score

