    def maxRectangleArea(self, points: List[List[int]]) -> int:
        # Convert points to a set for O(1) lookups
        point_set = set((x, y) for x, y in points)
        n = len(points)
        max_area = -1

        # Generate all possible combinations of x1, x2 and y1, y2
        from itertools import combinations

        # Extract all unique x and y coordinates
        x_coords = sorted({x for x, y in points})
        y_coords = sorted({y for x, y in points})

        for x1, x2 in combinations(x_coords, 2):
            for y1, y2 in combinations(y_coords, 2):
                # Check if all four corners exist
                corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
