    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        from collections import defaultdict, deque

        # Step 1: Build the graph
        graph = defaultdict(list)
        reverse_graph = defaultdict(list)
        for f, t in zip(flowFrom, flowTo):
            graph[f].append(t)
            reverse_graph[t].append(f)

        # Step 2: Find SCCs using Kosaraju's algorithm
        visited = set()
        order = []

        def dfs1(node):
            stack = [(node, False)]
            while stack:
                current, processed = stack.pop()
                if processed:
                    order.append(current)
                    continue
                if current in visited:
                    continue
                visited.add(current)
                stack.append((current, True))
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        stack.append((neighbor, False))

        for i in range(n):
            if i not in visited:
                dfs1(i)

        visited = set()
        sccs = []

        def dfs2(node, current_scc):
            stack = [node]
            visited.add(node)
            current_scc.append(node)
            while stack:
                current = stack.pop()
                for neighbor in reverse_graph[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        current_scc.append(neighbor)
                        stack.append(neighbor)

        for node in reversed(order):
            if node not in visited:
                current_scc = []
                dfs2(node, current_scc)
                sccs.append(current_scc)

        # Step 3: Build component graph (SCC -> component)
        component = [0] * n
        comp_id = 0
        for i, scc in enumerate(sccs):
            for node in scc:
                component[node] = comp_id
            comp_id += 1

        # Step 4: Build component graph (edges between components)
        comp_graph = defaultdict(list)
        comp_in_degree = defaultdict(int)
