            for v in graph[u]:
                if component[u] != component[v]:
                    comp_graph[component[u]].append(component[v])
                    comp_in_degree[component[v]] += 1

        # Step 5: Build component graph and find components with crystal
        has_crystal = [False] * len(sccs)
        for crystal in crystals:
            for comp in sccs:
                if crystal in comp:
                    has_crystal[component[crystal]] = True
                    break

        # Step 6: Topological sort of components
        # We use Kahn's algorithm for topological sort
        queue = deque()
        for comp in range(len(sccs)):
            if comp_in_degree[comp] == 0:
                queue.append(comp)

        topo_order = []
        while queue:
            u = queue.popleft()
            topo_order.append(u)
            for v in comp_graph[u]:
                comp_in_degree[v] -= 1
                if comp_in_degree[v] == 0:
                    queue.append(v)

        # Step 7: Count required edges
        # Process components in reverse topological order
        required_edges = 0
        # We need to find components that do not have a crystal and are not reachable from any crystal component
        # We process in reverse topological order (sink to source)
        for comp in reversed(topo_order):
            if not has_crystal[comp]:
                # This component needs to be connected to a component with crystal
                # Check if there is a crystal component that can reach it (i.e., in the DAG, there is an edge from crystal comp to this one)
                # We can use the component graph to find if there's any such component
                has_incoming_from_crystal = False
