class Solution:
    def minCost(self, nums: List[int]) -> int:
        from functools import lru_cache

        n = len(nums)

        @lru_cache(None)
        def dp(i, k):
            # i: start index of the subarray
            # k: number of elements remaining in the subarray
            if k == 1:
                return max(nums[i:i+1])
            if k == 2:
                return max(nums[i:i+2])
            if k == 3:
                # Try all possible combinations of removing 2 elements from the first 3
                # (0 and 1), (0 and 2), (1 and 2)
                return min(
                    max(nums[i], nums[i+1]) + dp(i+2, 1),
                    max(nums[i], nums[i+2]) + dp(i+2, 1),
                    max(nums[i+1], nums[i+2]) + dp(i+2, 1)
                )
            # If more than 3 elements, we try removing two elements from the first three
            # and then continue from the next index
            # Also, the total number of elements is more than 3, and we need to check all combinations
            return min(
                max(nums[i], nums[i+1]) + dp(i+2, k-2),
                max(nums[i], nums[i+2]) + dp(i+2, k-2),
                max(nums[i+1], nums[i+2]) + dp(i+2, k-2)
            )

        return dp(0, n)

