        # We can use memoization with the index of the array, and the current state of the array
        # However, since we are processing elements from the start, we can consider the problem in terms of the current position in the array.
        # We will pass the array as a list, but to avoid modifying the original, we can use a memoization approach with current index and elements remaining.

        # We use a helper function to find the minimum cost for a given subarray starting at position i.

        @lru_cache(maxsize=None)
        def helper(i):
            if i >= n:
                return 0
            if i + 1 >= n:
                return max(nums[i], nums[i+1]) if i < n - 1 else 0
            if i + 2 >= n:
                return max(nums[i], nums[i+1]) if i < n - 1 else 0

            min_cost = float('inf')

