        m, n = len(coins), len(coins[0])
        # Initialize a 3D DP array: dp[i][j][k] = max coins at (i,j) with k neutralizations used
        dp = [[[float('-inf') for _ in range(3)] for _ in range(n)] for _ in range(m)]

        # Base case: starting at (0, 0)
        dp[0][0][0] = coins[0][0] if coins[0][0] >= 0 else 0
        if coins[0][0] < 0:
            dp[0][0][1] = 0  # neutralizing this cell
            dp[0][0][2] = 0  # neutralizing this cell again (but it's not possible, so 0)

        # Fill the DP table
        for i in range(m):
            for j in range(n):
                # If current cell is the start (0,0), skip
                if i == 0 and j == 0:
                    continue
                # Try to come from the top (i-1, j)
                for k in range(3):
                    if dp[i-1][j][k] != float('-inf'):
                        current_value = coins[i][j]
                        # If current cell is not negative, take it as is
                        if current_value >= 0:
                            new_val = dp[i-1][j][k] + current_value
                            if new_val > dp[i][j][k]:
                                dp[i][j][k] = new_val
                        else:
                            # Two options: take it (not neutralize) or skip it (neutralize)
                            # 1. Not neutralize: subtract the absolute value
                            new_val_no_neutral = dp[i-1][j][k] - abs(current_value)
                            if new_val_no_neutral > dp[i][j][k]:
                                dp[i][j][k] = new_val_no_neutral
                            # 2. Neutralize: we can do it only if k < 2
