class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        from collections import deque

        m, n = len(grid), len(grid[0])
        start = (0, 0)
        end = (m - 1, n - 1)

        # BFS: Each state is (row, col, current_health)
        visited = set()
        queue = deque([(0, 0, health)])  # (row, col, health_remaining)
        visited.add((0, 0))

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            row, col, current_health = queue.popleft()

            if (row, col) == end:
                # We have reached the end, check if health is still >= 1
                if current_health >= 1:
                    return True
                else:
                    continue  # Not safe, move on

            # Try all four directions
            for dr, dc in directions:
                nr, nc = row + dr, col + dc

                # Check if new position is valid
                if 0 <= nr < m and 0 <= nc < n:
                    # Calculate the new health after moving to (nr, nc)
                    damage = grid[nr][nc]
                    new_health = current_health - damage

                    if new_health < 1:
                        continue  # Not safe to go here

                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc, new_health))

        # If no path was found that satisfies the condition
        return False

