    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        if grid[0][0] == 1:
            return health >= 2  # Start cell is unsafe, need at least 2 health to survive
        if grid[m - 1][n - 1] == 1:
            return health >= 2  # End cell is unsafe, need at least 2 health to survive

        # Directions: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # BFS queue: (i, j, current_health)
        queue = deque()
        queue.append((0, 0, health))

        # Visited set: (i, j, health) to avoid revisiting with the same or worse health
        visited = set()
        visited.add((0, 0, health))

        while queue:
            i, j, current_health = queue.popleft()

            # Check if we reached the end
            if i == m - 1 and j == n - 1:
                return current_health >= 1

            # Try all four directions
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n:
                    next_health = current_health - grid[ni][nj]
                    if next_health >= 1:
                        if (ni, nj, next_health) not in visited:
                            visited.add((ni, nj, next_health))
                            queue.append((ni, nj, next_health))

        # If we exhausted all paths and didn't reach the end safely
        return False

