    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        # For each starting index i, find the furthest end j where the subarray can be made non-decreasing with at most k operations
        for i in range(n):
            # We'll find the maximum j such that the required operations for nums[i..j] is <= k
            # Using a sliding window approach with prefix sums

            max_j = i
            ops = 0
            prev = nums[i]
            total_ops = 0

            for j in range(i, n):
                # Calculate required ops to make nums[j] >= prev
                if nums[j] < prev:
                    required = prev - nums[j]
                    total_ops += required
                    if total_ops > k:
                        break
                else:
                    total_ops += 0
                prev = nums[j]

                if total_ops <= k:
                    max_j = j
                else:
                    break

            # All subarrays from i to max_j are valid
            total += max_j - i + 1

        return total

