        for i in range(1, n + 1):
            # Try all possible valid prefixes that can end at i
            # Check all prefixes that are of length l, and match target[i-l:i]
            for l in range(1, i + 1):
                prefix = target[i - l:i]
                if prefix in all_prefixes:
                    if dp[i - l] + 1 < dp[i]:
                        dp[i] = dp[i - l] + 1

        # If the target can be formed
        if dp[n] == float('inf'):
            return -1
        else:
            return dp[n]

