        from typing import List

        def is_subsequence(s: str, t: str) -> bool:
            # Check if t is a subsequence of s
            it = iter(s)
            return all(c in it for c in t)

        # First, find the positions of the pattern in source
        # We'll use a list to store the indices of pattern characters in source
        pattern_indices = []
        ptr = 0
        for i, c in enumerate(source):
            if ptr < len(pattern) and c == pattern[ptr]:
