        if ptr < len(pattern):
            return 0  # Pattern not found in source (should not happen per problem constraints)

        # The pattern is a subsequence of source
        # Try to remove as many characters as possible from targetIndices
        # We will try to remove in the order of targetIndices, and see if pattern remains a subsequence

        # Keep track of which indices have been removed
        removed = set()
        count = 0
        # Sort the targetIndices in increasing order for greedy removal
        sorted_indices = sorted(targetIndices)

        for idx in sorted_indices:
            # Check if this index is not already removed
