    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        from typing import List

        def is_subsequence(s: str, t: str) -> bool:
            # Check if t is a subsequence of s
            it = iter(s)
            return all(c in it for c in t)

        # First, find the positions of the pattern in source
        # We'll use a list to store the indices of pattern characters in source
        pattern_indices = []
        ptr = 0
        for i, c in enumerate(source):
            if ptr < len(pattern) and c == pattern[ptr]:
                pattern_indices.append(i)
                ptr += 1
        if ptr < len(pattern):
            return 0  # Pattern not found in source (should not happen per problem constraints)

        # The pattern is a subsequence of source
        # Try to remove as many characters as possible from targetIndices
        # We will try to remove in the order of targetIndices, and see if pattern remains a subsequence

        # Keep track of which indices have been removed
        removed = set()
        count = 0
        # Sort the targetIndices in increasing order for greedy removal
        sorted_indices = sorted(targetIndices)

        for idx in sorted_indices:
            # Check if this index is not already removed
            if idx in removed:
                continue
            # Check if the current source (after removing removed indices) still contains the pattern as a subsequence
            # To simulate this, we need to build the source without removed indices
            # Then check if the pattern is a subsequence of the modified source
            # Build the modified source string
            modified_source = []
            for i in range(len(source)):
                if i not in removed:
                    modified_source.append(source[i])
            modified_source_str = ''.join(modified_source)

            if is_subsequence(modified_source_str, pattern):
                # It is still a subsequence, so we can remove this index
                removed.add(idx)
                count += 1
            else:
                # Cannot remove this index, so break (we can't remove more)
