class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True  # Zero substrings is always valid

        n = len(s)
        if k == 1:
            return self.is_special(s, n - 1)  # At least one valid special substring

        # Function to check if a substring is special
        def is_special(subs, start, end):
            # Check if all characters in subs appear only in this substring
            char_set = set(subs)
            for c in char_set:
                if s.count(c) > (end - start + 1):
                    return False
            return True

        # Function to collect all special substrings
        def collect_special_substrings():
            special = []
            n = len(s)
            for i in range(n):
                for j in range(i + 1, n):
                    sub = s[i:j]
                    if len(sub) < n and is_special(sub, i, j):
                        special.append((i, j))
            return special

        # Collect all possible special substrings
        special_substrings = collect_special_substrings()

        # If there are less than k substrings, return False
        if len(special_substrings) < k:
            return False

        # Try to select k disjoint substrings using a greedy approach
        selected = []
        current_pos = 0

        for sub in special_substrings:
            start, end = sub
            if start > current_pos:
                selected.append((start, end))
                current_pos = end + 1
                if len(selected) == k:
                    return True

        return False

