        # Check if all characters in the substring are unique to it
        char_set = set(subs)
        for c in char_set:
            count = 0
            for i in range(len(subs)):
                if subs[i] == c:
                    count += 1
            # If the character appears outside the substring
            if subs.count(c) != count:
                return False
        return True

