class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        if n < 2:
            return False

        # Preprocess: For each character, store all indices it appears in
        char_positions = {}
        for i, c in enumerate(s):
            if c not in char_positions:
                char_positions[c] = []
            char_positions[c].append(i)

        # Function to check if a substring is special (not the whole string, and all characters are unique within the substring)
        def is_special(subs):
            if len(subs) == n:
                return False
            chars = set(subs)
            for c in chars:
                if any(pos not in range(start, end + 1) for pos in char_positions[c]):
                    return False
            return True

        # Find all possible special substrings
        def find_special_substrings():
            substrings = []
            for i in range(n):
                for j in range(i + 1, n):
                    substr = s[i:j]
                    if is_special(substr):
                        substrings.append((i, j - 1, substr))
            return substrings

        special_substrings = find_special_substrings()

        # Now, try to select k non-overlapping special substrings
        # We use a greedy approach to pick the earliest possible non-overlapping substrings
        selected = []

        def can_select_k(substrings, k):
            count = 0
            i = 0
            while i < len(substrings) and count < k:
                # Find the first possible substring starting at or after current i
                for j in range(i, len(substrings)):
                    start, end, _ = substrings[j]
                    if start >= i:
                        # Try to select this substring
                        selected.append((start, end))
                        count += 1
                        i = end + 1
                        break
                else:
                    break
            return count >= k

        # Try to select k disjoint special substrings
        return can_select_k(special_substrings, k)

