class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        from collections import Counter

        if k == 0:
            return True

        # Count frequency of each character in the string
        freq = Counter(s)

        # Count how many characters appear exactly once (valid single-character special substrings)
        single_char_special = sum(1 for c in freq if freq[c] == 1)

        # If we have enough single-character special substrings, it's possible
        if single_char_special >= k:
            return True
        else:
            # Otherwise, if k is too large, not possible
            if k > len(s) // 2:
                return False
            return False

